// NodeServiceHandler is an implementation of the raycontrol.node.v1.NodeService service.
type NodeServiceHandler interface {
	GetStatus(context.Context, *connect.Request[v1.GetStatusRequest]) (*connect.Response[v1.GetStatusResponse], error)
	ListUsers(context.Context, *connect.Request[v1.ListUsersRequest]) (*connect.Response[v1.ListUsersResponse], error)
	CreateUser(context.Context, *connect.Request[v1.CreateUserRequest]) (*connect.Response[v1.CreateUserResponse], error)
	SetUserEnabled(context.Context, *connect.Request[v1.SetUserEnabledRequest]) (*connect.Response[v1.SetUserEnabledResponse], error)
	SetUserServices(context.Context, *connect.Request[v1.SetUserServicesRequest]) (*connect.Response[v1.SetUserServicesResponse], error)
	DeleteUser(context.Context, *connect.Request[v1.DeleteUserRequest]) (*connect.Response[v1.DeleteUserResponse], error)
	// ExportUser returns a user's profiles: the links of their subscription
	// (docs/spec/subscription-v1.md §4), each with the next one while a
	// switch is pending (P-10). They hold the user's credentials, so the
	// call is audited. They work only from an address SPA has opened.
	ExportUser(context.Context, *connect.Request[v1.ExportUserRequest]) (*connect.Response[v1.ExportUserResponse], error)
	ListServices(context.Context, *connect.Request[v1.ListServicesRequest]) (*connect.Response[v1.ListServicesResponse], error)
	CreateService(context.Context, *connect.Request[v1.CreateServiceRequest]) (*connect.Response[v1.CreateServiceResponse], error)
	SetServiceEnabled(context.Context, *connect.Request[v1.SetServiceEnabledRequest]) (*connect.Response[v1.SetServiceEnabledResponse], error)
	DeleteService(context.Context, *connect.Request[v1.DeleteServiceRequest]) (*connect.Response[v1.DeleteServiceResponse], error)
	// RotateService asks for the next key switch of a REALITY service
	// (docs/08-decisions.md, R4-7): a lead time away, so that clients get the
	// next keys first, or at once (leaked keys, a blocked name). For a dnstt
	// service it switches the seal key at once (spec/dnsseal-v1.md §8): the
	// previous one stays accepted for the credential grace, unless now.
	RotateService(context.Context, *connect.Request[v1.RotateServiceRequest]) (*connect.Response[v1.RotateServiceResponse], error)
	// SetServiceOption changes one of the few settings that may change after
	// creation: a site's answer, whether REALITY moves its server name,
	// Hysteria2's Brutal ceilings, Yggdrasil's public peers.
	SetServiceOption(context.Context, *connect.Request[v1.SetServiceOptionRequest]) (*connect.Response[v1.SetServiceOptionResponse], error)
	// SetCertificate puts the operator's own certificate on a site, in place
	// of one from ACME, for every service under it (REALITY self-steal,
	// hy2-masq, naive, DoH, Yggdrasil). With ACME on, rayd renews it when it
	// is due. On the node only: it carries the private key.
	SetCertificate(context.Context, *connect.Request[v1.SetCertificateRequest]) (*connect.Response[v1.SetCertificateResponse], error)
	ListDevices(context.Context, *connect.Request[v1.ListDevicesRequest]) (*connect.Response[v1.ListDevicesResponse], error)
	// CreateDevice returns the device bundle with the device key. The key is
	// not stored anywhere it can be read back through the API.
	CreateDevice(context.Context, *connect.Request[v1.CreateDeviceRequest]) (*connect.Response[v1.CreateDeviceResponse], error)
	// RevokeDevice revokes a device, or withdraws an unused invite.
	RevokeDevice(context.Context, *connect.Request[v1.RevokeDeviceRequest]) (*connect.Response[v1.RevokeDeviceResponse], error)
	// CreateInvite returns a one-time invite ("rcinv1:..."): the client
	// registers the device itself through the remote API (R3-3).
	CreateInvite(context.Context, *connect.Request[v1.CreateInviteRequest]) (*connect.Response[v1.CreateInviteResponse], error)
	ListAudit(context.Context, *connect.Request[v1.ListAuditRequest]) (*connect.Response[v1.ListAuditResponse], error)
	// Admin access: addresses (CIDR) that reach SSH without SPA (emergency
	// access, docs/08-decisions.md D-6).
	GetAdminAccess(context.Context, *connect.Request[v1.GetAdminAccessRequest]) (*connect.Response[v1.GetAdminAccessResponse], error)
	SetAdminAccess(context.Context, *connect.Request[v1.SetAdminAccessRequest]) (*connect.Response[v1.SetAdminAccessResponse], error)
	// Relays in front of the node (relay-v1): one address each, which
	// reaches the service ports without SPA. Adding and removing is for
	// root on the node only: a relay opens the perimeter.
	AddRelay(context.Context, *connect.Request[v1.AddRelayRequest]) (*connect.Response[v1.AddRelayResponse], error)
	ListRelays(context.Context, *connect.Request[v1.ListRelaysRequest]) (*connect.Response[v1.ListRelaysResponse], error)
	RemoveRelay(context.Context, *connect.Request[v1.RemoveRelayRequest]) (*connect.Response[v1.RemoveRelayResponse], error)
	// IssueRelayBundle makes the relay a new client certificate (the one
	// before stops working) and returns what its host needs (relay-v1 §3).
	// It holds the relay's private key: root on the node only.
	IssueRelayBundle(context.Context, *connect.Request[v1.IssueRelayBundleRequest]) (*connect.Response[v1.IssueRelayBundleResponse], error)
	// SetRelayAccess changes the relay host's SSH port and admin addresses
	// without a new bundle: its SPA and certificate stay.
	SetRelayAccess(context.Context, *connect.Request[v1.SetRelayAccessRequest]) (*connect.Response[v1.SetRelayAccessResponse], error)
	// The DNS provider (Cloudflare): the node's records in its zone and
	// certificates through DNS-01 with a wildcard name (R4-10). The token is
	// stored by rayd and never returned.
	SetDNSProvider(context.Context, *connect.Request[v1.SetDNSProviderRequest]) (*connect.Response[v1.SetDNSProviderResponse], error)
	GetDNS(context.Context, *connect.Request[v1.GetDNSRequest]) (*connect.Response[v1.GetDNSResponse], error)
	SyncDNS(context.Context, *connect.Request[v1.SyncDNSRequest]) (*connect.Response[v1.SyncDNSResponse], error)
	RemoveDNS(context.Context, *connect.Request[v1.RemoveDNSRequest]) (*connect.Response[v1.RemoveDNSResponse], error)
	// Backup returns a consistent copy of the node's database. Root only: it
	// holds every key (R4-13); rayctl encrypts it with the operator's
	// passphrase, which never reaches rayd.
	Backup(context.Context, *connect.Request[v1.BackupRequest]) (*connect.Response[v1.BackupResponse], error)
	// GetMetrics returns aggregate metrics in the Prometheus text format, no
	// names of users, devices or services (R4-14).
	GetMetrics(context.Context, *connect.Request[v1.GetMetricsRequest]) (*connect.Response[v1.GetMetricsResponse], error)
	// GetSummary returns the state of the client summaries (R4-21): whether
	// the node takes reports, the AS lookup, and the networks with at least
	// k reports; smaller groups only as a total.
	GetSummary(context.Context, *connect.Request[v1.GetSummaryRequest]) (*connect.Response[v1.GetSummaryResponse], error)
	// SetSummary turns the reports on or off, and the online AS lookup. The
	// token is stored by rayd and never returned.
	SetSummary(context.Context, *connect.Request[v1.SetSummaryRequest]) (*connect.Response[v1.SetSummaryResponse], error)
	// SetDebug opens the debug window for a while or closes it: rayd, rayspa
	// and niko-server log at debug level until it ends by itself
	// (docs/09-observability.md §3). Root on the node only.
	SetDebug(context.Context, *connect.Request[v1.SetDebugRequest]) (*connect.Response[v1.SetDebugResponse], error)
	// GetDeployment returns what root must install for the current services:
	// system users, unit files and other files. rayctl apply writes them.
	GetDeployment(context.Context, *connect.Request[v1.GetDeploymentRequest]) (*connect.Response[v1.GetDeploymentResponse], error)
}

